export interface Industry {
  name: string;
  /** % share of GDP this industry represents */
  gdpShare: number;
  /** hex or hsl color for the bar */
  color: string;
}

export interface MilitaryStats {
  /** Annual defense budget in billions USD */
  budgetBn: number;
  /** Active-duty personnel */
  activeTroops: number;
  /** Reserve personnel */
  reserveTroops: number;
  /** Global Firepower index rank (1 = strongest) */
  globalFirepowerRank: number;
  /** Nuclear warheads (0 if none) */
  nuclearWarheads: number;
  /** Key capability tags */
  capabilities: string[];
}

export interface EnergyStats {
  /** Total primary energy consumption in TWh/year */
  totalUseTWh: number;
  /** Total primary energy production in TWh/year */
  totalProductionTWh: number;
  /** Energy mix breakdown (% of total production) */
  mix: { source: string; pct: number; color: string }[];
}

export interface PMIStats {
  /** Composite PMI (manufacturing + services weighted average) */
  composite: number;
  /** Manufacturing PMI */
  manufacturing: number;
  /** Services PMI */
  services: number;
  /** Month/year of reading, e.g. "Mar 2025" */
  period: string;
  /** Direction vs prior month: "expanding" | "contracting" | "neutral" */
  trend: "expanding" | "contracting" | "neutral";
}

/** High-level classification of a country's economic system */
export type EconomyType =
  | "Mixed Market Economy"
  | "Free Market Economy"
  | "Social Market Economy"
  | "State-Directed Economy"
  | "Command Economy"
  | "Transition Economy"
  | "Resource-Dependent Economy"
  | "Aid-Dependent Economy"
  | "Offshore Financial Economy"
  | "Tourism-Dependent Economy";

export interface Country {
  id: string;
  name: string;
  code: string;
  continent: string;
  capital: string;
  /** High-level classification of economic system. Not yet populated for any
   *  country — optional like every other enrichment field on this interface. */
  economyType?: EconomyType;
  population: number;
  gdp: number; // billions USD
  gdpPerCapita: number;
  gdpGrowth: number;
  currency: string;
  governmentType: string;
  headOfState: string;
  officialLanguages: string[];
  spokenLanguages?: string[];
  landmarks?: string[];
  religions?: string[];
  /** Dominant political ideologies (e.g. Liberal Democracy, Nationalism, Socialism) */
  politicalIdeologies?: string[];
  /** Governance style tags (e.g. Welfare State, Rule of Law, Authoritarian, Theocracy) */
  governanceStyle?: string[];
  /** Top industries by GDP share */
  keyIndustries?: Industry[];
  /** Energy use & production statistics */
  energy?: EnergyStats;
  /** PMI — Purchasing Managers&#39; Index */
  pmi?: PMIStats;
  /** Military statistics */
  military?: MilitaryStats;
  unemploymentRate: number;
  lifeExpectancy: number;
  humanDevelopmentIndex: number;
  tradeBalance: number; // billions
  inflationRate: number;
  areaKm2: number;
  trends: { year: string; gdp: number; hdi: number }[];
  /** Homeless persons per 100,000 residents */
  homelessnessRate?: number;
  /** Incarcerated persons per 100,000 residents */
  incarcerationRate?: number;
}

// Helper to build a military object
function mkMilitary(
  budgetBn: number,
  activeTroops: number,
  reserveTroops: number,
  globalFirepowerRank: number,
  nuclearWarheads: number,
  capabilities: string[],
): MilitaryStats {
  return {
    budgetBn,
    activeTroops,
    reserveTroops,
    globalFirepowerRank,
    nuclearWarheads,
    capabilities,
  };
}

// Helper to build a PMI object
function mkPMI(
  composite: number,
  manufacturing: number,
  services: number,
  period: string,
): PMIStats {
  const trend: PMIStats["trend"] =
    composite > 50 ? "expanding" : composite < 50 ? "contracting" : "neutral";
  return { composite, manufacturing, services, period, trend };
}

// Helper to build an energy object
function mkEnergy(
  useTWh: number,
  prodTWh: number,
  mix: [string, number, string][],
): EnergyStats {
  return {
    totalUseTWh: useTWh,
    totalProductionTWh: prodTWh,
    mix: mix.map(([source, pct, color]) => ({ source, pct, color })),
  };
}

function mkTrends(
  gdp2026: number,
  hdi: number,
): { year: string; gdp: number; hdi: number }[] {
  const years = ["2022", "2023", "2024", "2025", "2026"];
  return years.map((year, i) => ({
    year,
    gdp: Math.round(gdp2026 * (0.88 + i * 0.03)),
    hdi: parseFloat((hdi - 0.01 + i * 0.003).toFixed(3)),
  }));
}

